#include <Adafruit_SSD1306.h>
#include <Adafruit_GFX.h>
// Arduino Sketch#include <WiFi.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <time.h>

// =========================
// WIFI
// =========================
const char* ssid = "FPT_GIA_PHONG";
const char* password = "giaphong123";

// =========================
// OLED
// =========================
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

#define OLED_RESET -1
#define OLED_ADDRESS 0x3C

Adafruit_SSD1306 display(
  SCREEN_WIDTH,
  SCREEN_HEIGHT,
  &Wire,
  OLED_RESET
);

// =========================
// NTP - GIỜ VIỆT NAM
// =========================
const char* ntpServer = "pool.ntp.org";

const long gmtOffset_sec = 7 * 3600;
const int daylightOffset_sec = 0;

// =========================
// THỨ
// =========================
const char* days[] = {
  "CN",
  "THU 2",
  "THU 3",
  "THU 4",
  "THU 5",
  "THU 6",
  "THU 7"
};

void setup() {

  Serial.begin(115200);

  // -------------------------
  // OLED
  // -------------------------
  Wire.begin(8, 9);

  if (!display.begin(
        SSD1306_SWITCHCAPVCC,
        OLED_ADDRESS
      )) {

    Serial.println("Khong tim thay OLED!");

    while (true) {
      delay(1000);
    }
  }

  display.clearDisplay();

  display.setTextColor(SSD1306_WHITE);

  display.setTextSize(1);
  display.setCursor(25, 10);
  display.println("DONG HO ESP32");

  display.setCursor(30, 30);
  display.println("Dang ket noi...");

  display.display();

  // -------------------------
  // WIFI
  // -------------------------
  WiFi.begin(ssid, password);

  Serial.print("Dang ket noi WiFi");

  while (WiFi.status() != WL_CONNECTED) {

    delay(500);

    Serial.print(".");
  }

  Serial.println();
  Serial.println("WiFi OK");

  // -------------------------
  // NTP
  // -------------------------
  configTime(
    gmtOffset_sec,
    daylightOffset_sec,
    ntpServer
  );

  struct tm timeinfo;

  while (!getLocalTime(&timeinfo)) {

    Serial.println("Dang lay thoi gian...");

    delay(500);
  }

  Serial.println("Da lay duoc gio!");
}

void loop() {

  struct tm timeinfo;

  if (!getLocalTime(&timeinfo)) {

    display.clearDisplay();

    display.setTextSize(1);
    display.setCursor(20, 25);
    display.println("Mat ket noi WiFi");

    display.display();

    delay(1000);

    return;
  }

  // =========================
  // HIEN THI
  // =========================

  char timeString[20];

  sprintf(
    timeString,
    "%02d:%02d:%02d",
    timeinfo.tm_hour,
    timeinfo.tm_min,
    timeinfo.tm_sec
  );

  char dateString[20];

  sprintf(
    dateString,
    "%02d/%02d/%04d",
    timeinfo.tm_mday,
    timeinfo.tm_mon + 1,
    timeinfo.tm_year + 1900
  );

  display.clearDisplay();

  // -------------------------
  // GIO
  // -------------------------

  display.setTextSize(2);

  display.setCursor(15, 5);

  display.println(timeString);

  // -------------------------
  // THU
  // -------------------------

  display.setTextSize(1);

  display.setCursor(43, 32);

  display.println(days[timeinfo.tm_wday]);

  // -------------------------
  // NGAY
  // -------------------------

  display.setTextSize(1);

  display.setCursor(38, 47);

  display.println(dateString);

  display.display();

  delay(200);
}
